const markMovedCopiesDirtyInCalendar = `-- name: MarkMovedCopiesDirtyInCalendar :exec
INSERT INTO sync_resources (calendar_id, uid, owner_type, dirty, sync_strategy)
SELECT c.id, m.uid, x.owner_type, 1, 'sync-token'
FROM calendars c
JOIN (
    SELECT t.uid FROM tombstones t WHERE t.moved_to_calendar_id = CAST(?1 AS INTEGER)
    UNION
    SELECT sc.uid FROM sync_conflicts sc
    WHERE sc.calendar_id = ?1 AND sc.move_source_calendar_id IS NOT NULL AND sc.resolved_at IS NULL
) m
JOIN (
    SELECT e.uid, 'event' AS owner_type FROM events e WHERE e.calendar_id = ?1 AND e.deleted_at IS NULL
    UNION
    SELECT td.uid, 'todo' AS owner_type FROM todos td WHERE td.calendar_id = ?1 AND td.deleted_at IS NULL
    UNION
    SELECT j.uid, 'journal' AS owner_type FROM journals j WHERE j.calendar_id = ?1 AND j.deleted_at IS NULL
) x ON x.uid = m.uid
WHERE c.id = ?1 AND c.account_id IS NOT NULL AND c.account_id != 0
ON CONFLICT(calendar_id, uid) DO NOTHING
`

// Give each live moved copy in a linked calendar a dirty sync row. The query
// starts from the moves into the calendar: the move tombstones that name it
// as the target, and the open move conflicts on it. A UID of such a move
// with a live row in the calendar is a moved copy. A copy in a local
// calendar has no sync row. After a link or a reset, the copy then pushes,
// and the view live_move_copies counts it. An existing row stays as it is.
// See issue #841.
func (q *Queries) MarkMovedCopiesDirtyInCalendar(ctx context.Context, calendarID int64) error {
	_, err := q.db.ExecContext(ctx, markMovedCopiesDirtyInCalendar, calendarID)
	return err
}

