func (q *Queries) MarkSyncResourceDirtyWithEtag(ctx context.Context, arg MarkSyncResourceDirtyWithEtagParams) error {
	_, err := q.db.ExecContext(ctx, markSyncResourceDirtyWithEtag, arg.Etag, arg.CalendarID, arg.Uid)
	return err
}

const markTombstoneSourceGone = `-- name: MarkTombstoneSourceGone :execrows
UPDATE tombstones SET source_gone = 1
WHERE id = ?1 AND version = ?2
`

type MarkTombstoneSourceGoneParams struct {
	ID      int64
	Version int64
}

// Mark the server object of one tombstone as gone, at the version that the
// caller read. An open move conflict of a third calendar holds the
// tombstone, so the clear keeps it. The flag does not change the version.
// See issue #841.
func (q *Queries) MarkTombstoneSourceGone(ctx context.Context, arg MarkTombstoneSourceGoneParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, markTombstoneSourceGone, arg.ID, arg.Version)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const recordSyncResourcePushFailure = `-- name: RecordSyncResourcePushFailure :exec
UPDATE sync_resources
SET push_fail_count = push_fail_count + 1,
    last_push_error = ?,
    wait_kind = 0,
    wait_holder_calendar_id = 0
WHERE calendar_id = ? AND uid = ?
`

type RecordSyncResourcePushFailureParams struct {
	LastPushError string
	CalendarID    int64
	Uid           string
}

// One more consecutive failed push attempt for this resource. The engine
// and the sync doctor call this after a push attempt that fails on an
// export, a parse, or a PUT. The doctor reads the counter to show how long
// a resource stayed wedged.
// A failure replaces a wait, so it clears the wait columns.
func (q *Queries) RecordSyncResourcePushFailure(ctx context.Context, arg RecordSyncResourcePushFailureParams) error {
	_, err := q.db.ExecContext(ctx, recordSyncResourcePushFailure, arg.LastPushError, arg.CalendarID, arg.Uid)
	return err
}

const retargetMoveTombstones = `-- name: RetargetMoveTombstones :exec
UPDATE tombstones SET moved_to_calendar_id = ?1, version = version + 1
WHERE uid = ?2 AND moved_to_calendar_id = ?3
`

type RetargetMoveTombstonesParams struct {
	ToCalendarID   *int64
	Uid            string
	FromCalendarID *int64
}

// Point the move tombstones of one UID that name from_calendar_id as the
// target at to_calendar_id. A chain move (A to B, then B to C before any
// sync) leaves the tombstone of A with the target B. B then holds no row of
// the UID any more. See issue #841.
func (q *Queries) RetargetMoveTombstones(ctx context.Context, arg RetargetMoveTombstonesParams) error {
	_, err := q.db.ExecContext(ctx, retargetMoveTombstones, arg.ToCalendarID, arg.Uid, arg.FromCalendarID)
	return err
}

const setSyncResourceCreateConflictRef = `-- name: SetSyncResourceCreateConflictRef :exec
UPDATE sync_resources SET remote_url = ?, etag = ?, dirty = 1, rev = rev + 1
WHERE calendar_id = ? AND uid = ? AND remote_url = ''
`

type SetSyncResourceCreateConflictRefParams struct {
	RemoteUrl  string
	Etag       string
	CalendarID int64
	Uid        string
}

// Mark a row without a server object dirty with the href and the etag of
// the object at its planned href. The local pick of an edit conflict on a
// create uses it, so the push sends If-Match. See issue #841.
func (q *Queries) SetSyncResourceCreateConflictRef(ctx context.Context, arg SetSyncResourceCreateConflictRefParams) error {
	_, err := q.db.ExecContext(ctx, setSyncResourceCreateConflictRef,
		arg.RemoteUrl,
		arg.Etag,
		arg.CalendarID,
		arg.Uid,
	)
	return err
}

const setSyncResourceEtag = `-- name: SetSyncResourceEtag :exec
UPDATE sync_resources SET etag = ? WHERE calendar_id = ? AND uid = ?
`

type SetSyncResourceEtagParams struct {
	Etag       string
	CalendarID int64
	Uid        string
}

// Replace the last known etag of a sync row. The dirty flag and the rev
// stay. A resolved move conflict sets the etag of the source row to the
// etag of the remote edit, so the conditional source DELETE matches. See
// issue #841.
func (q *Queries) SetSyncResourceEtag(ctx context.Context, arg SetSyncResourceEtagParams) error {
	_, err := q.db.ExecContext(ctx, setSyncResourceEtag, arg.Etag, arg.CalendarID, arg.Uid)
	return err
}

const setSyncResourceWait = `-- name: SetSyncResourceWait :exec
UPDATE sync_resources
SET wait_kind = ?1, wait_holder_calendar_id = ?2
WHERE calendar_id = ?3 AND uid = ?4
`

type SetSyncResourceWaitParams struct {
	WaitKind             int64
	WaitHolderCalendarID int64
	CalendarID           int64
	Uid                  string
}

// Record that the push of a sync row waits for another step. wait_kind is 1
// for a hold by an open move conflict of wait_holder_calendar_id, and 2 for
// a wait for a source delete. A wait is no failure, so push_fail_count and
// last_push_error stay as they are. See issue #841.
func (q *Queries) SetSyncResourceWait(ctx context.Context, arg SetSyncResourceWaitParams) error {
	_, err := q.db.ExecContext(ctx, setSyncResourceWait,
		arg.WaitKind,
		arg.WaitHolderCalendarID,
		arg.CalendarID,
		arg.Uid,
	)
	return err
}

const upsertDirtySyncResourceOfCalendar = `-- name: UpsertDirtySyncResourceOfCalendar :exec
INSERT INTO sync_resources (calendar_id, uid, owner_type, dirty, sync_strategy)
VALUES (?1, ?2, ?3, 1, 'sync-token')
ON CONFLICT(calendar_id, uid) DO UPDATE SET dirty = 1, rev = rev + 1
`

type UpsertDirtySyncResourceOfCalendarParams struct {
	CalendarID int64
	Uid        string
	OwnerType  string
}

// Mark the sync row of uid in exactly calendar_id dirty with a new rev, and
// create the row when it does not exist. It does not move the mark to
// another calendar. MarkResourceDirty runs it after its own redirect, and
// the settle of a gone move source runs it for the row of the moved copy.
// So one statement holds the write. See issue #841.
func (q *Queries) UpsertDirtySyncResourceOfCalendar(ctx context.Context, arg UpsertDirtySyncResourceOfCalendarParams) error {
	_, err := q.db.ExecContext(ctx, upsertDirtySyncResourceOfCalendar, arg.CalendarID, arg.Uid, arg.OwnerType)
	return err
}

const upsertSyncResource = `-- name: UpsertSyncResource :exec
INSERT INTO sync_resources (calendar_id, uid, owner_type, remote_url, etag, dirty, sync_strategy)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(calendar_id, uid) DO UPDATE SET
    remote_url = excluded.remote_url,
    etag = excluded.etag,
    dirty = MAX(sync_resources.dirty, excluded.dirty),
    sync_strategy = excluded.sync_strategy
`

type UpsertSyncResourceParams struct {
	CalendarID   int64
	Uid          string
	OwnerType    string
	RemoteUrl    string
	Etag         string
	Dirty        int64
	SyncStrategy string
}

func (q *Queries) UpsertSyncResource(ctx context.Context, arg UpsertSyncResourceParams) error {
	_, err := q.db.ExecContext(ctx, upsertSyncResource,
		arg.CalendarID,
		arg.Uid,
		arg.OwnerType,
		arg.RemoteUrl,
		arg.Etag,
		arg.Dirty,
		arg.SyncStrategy,
	)
	return err
}
